-- Read-only shared reference catalogs (bundled exercises, ingredients, recipes).
-- Populated by supabase/seed.sql (generated by scripts/gen-reference-seed.mts from src/data/*).
-- Readable by anon + authenticated; NO write grants for any client role.

create table public.ref_exercises (
  id text primary key check (id ~ '^[a-z0-9][a-z0-9-]{0,99}$'),
  name text not null,
  category text not null,
  pattern text not null,
  equipment text[] not null default '{}',
  primary_muscles text[] not null default '{}',
  tracking text not null,
  load_convention text not null,
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  updated_at timestamptz not null default now()
);
create index ref_exercises_pattern on public.ref_exercises (pattern);

create table public.ref_ingredients (
  id text primary key check (char_length(id) between 1 and 100),
  name text not null,
  category text not null,
  state text not null,
  allergens text[] not null default '{}',
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  updated_at timestamptz not null default now()
);

create table public.ref_recipes (
  id text primary key check (char_length(id) between 1 and 100),
  name text not null,
  meal text not null,
  servings numeric not null check (servings > 0),
  data jsonb not null check (jsonb_typeof(data) = 'object'),
  updated_at timestamptz not null default now()
);

do $$
declare t text;
begin
  foreach t in array array['ref_exercises', 'ref_ingredients', 'ref_recipes'] loop
    execute format('alter table public.%I enable row level security', t);
    execute format('revoke all on table public.%I from public, anon, authenticated', t);
    execute format('grant select on table public.%I to anon, authenticated', t);
    execute format('create policy "reference data is readable" on public.%I for select to anon, authenticated using (true)', t);
  end loop;
end $$;
